package lk.medical.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.io.*; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.util.*;
@Component public class TextFileStore { private final Path directory; public TextFileStore(@Value("${app.data-dir:data}") String dir){Path p=Paths.get(dir);directory=p.isAbsolute()?p:Paths.get(System.getProperty("user.dir")).resolve(p);try{Files.createDirectories(directory);for(String f:List.of("users.txt","doctors.txt","appointments.txt","medical-records.txt")){Path file=directory.resolve(f);if(Files.notExists(file))Files.createFile(file);}}catch(IOException e){throw new IllegalStateException("Cannot initialise data files",e);}} public synchronized List<String> read(String file){try(BufferedReader r=Files.newBufferedReader(directory.resolve(file),StandardCharsets.UTF_8)){List<String> out=new ArrayList<>();String line;while((line=r.readLine())!=null)if(!line.isBlank())out.add(line);return out;}catch(IOException e){throw new UncheckedIOException(e);}} public synchronized void write(String file,List<String> lines){try(BufferedWriter w=Files.newBufferedWriter(directory.resolve(file),StandardCharsets.UTF_8,StandardOpenOption.TRUNCATE_EXISTING)){for(String line:lines){w.write(line);w.newLine();}}catch(IOException e){throw new UncheckedIOException(e);}} public static String enc(String s){return Base64.getUrlEncoder().withoutPadding().encodeToString(Objects.toString(s,"").getBytes(StandardCharsets.UTF_8));} public static String dec(String s){return new String(Base64.getUrlDecoder().decode(s),StandardCharsets.UTF_8);} public Path getDirectory(){return directory;} }
